import { isHotReload, isStateRestoreEnabled, status, toast } from "./client/status_bar.ts";
import { StateTracker } from "./client/tracker.ts";
import { delayed, HOST, log, sleep } from "./client/util.ts";
import { startWebsocketSession } from "./client/websocket.ts";
import { getUrlWithRawQuery, handleLocationSwitchInIFrame } from "./client/location.ts";

let thePathname: string = globalThis.location.pathname;
let stateTracker: StateTracker | undefined = undefined;
let prevFrame: HTMLIFrameElement | undefined = undefined;
let nextZIndex = 100;
let isReloading = false;

const main = async () => {
    if (handleLocationSwitchInIFrame()) {
        return;
    }

    log("starting");
    status("", "");
    await hotReload(true);

    startWebsocketSession(`ws://${HOST}/`, async () => {
        if (!isHotReload()) {
            globalThis.location.reload();
            return;
        }
        log("start reload");
        stopCleanup();
        const startTime = performance.now();
        status("yellow", "reloading...");
        await hotReload(false);
        const elapsed = Math.floor(performance.now() - startTime);
        status("green", "connected", false);
        toast("green", `reloaded in ${elapsed}ms`);
    });
    window.addEventListener("popstate", async (e) => {
        if (!isHotReload()) {
            setTimeout(() => {
                globalThis.location.reload();
            }, 100);
        }
        // const pathname = e.state.pathname;
        // log("popping state to: "+pathname);
        // if (pathname && typeof pathname === "string") {
        //     const frames = document.querySelectorAll<HTMLIFrameElement>("iframe.content-frame");
        //     const len = frames.length;
        //     for (let i =0;i<len;i++) {
        //         frames[i].style.zIndex= "1";
        //     }
        //     // log("hot reloading: "+pathname);
        //     // thePathname = pathname;
        //     // await hotReload(false);
        // }
    })
};

const CLEANUP_INTERVAL_MS = 5000;

let cleanupTimer: ReturnType<typeof setTimeout> | undefined = undefined;

const stopCleanup = () => {
    clearTimeout(cleanupTimer);
    cleanupTimer = undefined;
};

const scheduleCleanup = () => {
    stopCleanup();
    cleanupTimer = setTimeout(function tick() {
        const frame = document.querySelector(".content-frame-todelete");
        if (!frame) {
            cleanupTimer = undefined;
            return;
        }
        frame.remove();
        cleanupTimer = setTimeout(tick, CLEANUP_INTERVAL_MS);
    }, CLEANUP_INTERVAL_MS);
};

const hotReload = async (isFirst: boolean) => {
    while (isReloading) {
        await sleep(10);
    }
    isReloading = true;
    const prevTracker = stateTracker;
    stateTracker = undefined;
    prevTracker?.stop();

    const frame = document.createElement("iframe");

    // if (!isFirst) {
{
        const cancel = delayed(() => {
            if (!isFirst) {
                status("yellow", "reloading: fetching...");
            }
        });
        // load new frame
        frame.allow =
            " ";
        frame.setAttribute(
            "sandbox",
            "allow-downloads allow-forms allow-modals allow-orientation-lock allow-pointer-lock allow-popups allow-popups-to-escape-sandbox allow-presentation allow-same-origin allow-scripts allow-top-navigation allow-top-navigation-by-user-activation allow-top-navigation-to-custom-protocols",
        );
        frame.className = "content-frame";
        frame.style.zIndex = "10";

        const frameLoadedPromise = new Promise<void>((resolve) => {
            frame.onload = () => resolve();
        });
        frame.dataset.loadpath = thePathname;
        frame.src = getUrlWithRawQuery({
            pathname: thePathname,
            search: globalThis.location.search,
            hash: globalThis.location.hash,
        });
        log("loading new frame: "+frame.src);
        document.body.append(frame);

        await frameLoadedPromise;
        if (isFirst) {
            status("", `rendered in ${Math.floor(performance.now())}ms`)
        }
        cancel();
    }

    // Copy title and favicon from frame into hosting document
    const frameDoc = frame.contentDocument;
    if (frameDoc) {
        const title = frameDoc.querySelector("title");
        if (title) {
            document.title = title.textContent ?? "";
        }
        // Remove all existing icons then insert the frame's icon if present
        document.querySelectorAll("link[rel~='icon']").forEach((el) => el.remove());
        const icon = frameDoc.querySelector("link[rel~='icon']");
        if (icon) {
            document.head.append(icon.cloneNode());
        }
    }

    if (isStateRestoreEnabled()) {
        const cancel = delayed(() => {
            if (!isFirst) {
                status("yellow", "reloading: restoring state...");
            }
        });

        if (thePathname === prevTracker?.pathname) {
            const nextTracker = new StateTracker(thePathname, frame, prevTracker?.getLastStabilizationTimeMs());
            await nextTracker.start();
            prevTracker?.apply(frame);
            stateTracker = nextTracker;
        } else {
            const nextTracker = new StateTracker(thePathname, frame, undefined);
            await nextTracker.start();
            stateTracker = nextTracker;
        }

        cancel();
    }

    // put it on top
    frame.style.zIndex = `${nextZIndex++}`;
    if (prevFrame) {
        prevFrame.style.display = "none";
        prevFrame.classList.add("content-frame-todelete");
    }
    prevFrame = frame;

    scheduleCleanup();
    isReloading = false;
};

void main();
