import { log } from "./util";

/**
 * Handle the case when user clicks on a link inside a wrapped iframe.
 *
 * In that case, the frame will navigate to that page, which will load
 * another wrapped page. So we want to immediately check if we are inside
 * a wrapped iframe. If so, we tell the top (hosting) page to navigate there
 * if it's not already there.
 */
export const handleLocationSwitchInIFrame = (): boolean => {
    log("preparing: "+window.self.location.pathname + window.self.location.search);
    if (isInWrappedIFrame()) {
        return true;
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (window as any)["__shwoop_top_page"] = true;
    return false;
};

const isInWrappedIFrame = (): boolean => {
    try {
        if (window.self === window.top) {
            // we are top frame, not wrapped
            log("in top frame");
            return false;
        }
        const topWindow = window.top;
        if (!topWindow) {
            log("no top frame");
            return false;
        }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        if (!(topWindow as any)["__shwoop_top_page"]) {
            log("top frame is not shwoop");
            return false;
        }

        const thePathname = (window.frameElement as HTMLIFrameElement).dataset.loadpath || window.self.location.pathname;

        log("selflocation="+window.self.location.pathname+", loadpath="+thePathname);

        // we are in an iframe that's hosted
        // redirect to raw to make the iframe load the raw content
        // and then set the url of the top window in history
        const l = window.self.location;
        log("pushing state to: "+l.pathname);
        topWindow.history.pushState({ pathname: l.pathname}, "", l.pathname);
        window.self.location.href = getUrlWithRawQuery(window.self.location);
        return true;
    } catch {
            log("access error - not wrapped");
        // access error, must mean we are not wrapped
        return false;
    }
};

type LocationPart = {
    pathname: string,
    search: string,
    hash: string,
}

export const getUrlWithRawQuery = (l: LocationPart): string => {
    let search = l.search;
    if (search.startsWith("?")) {
        search += "&";
    } else {
        search = "?";
    }
    search += "x-shwoop-is-raw=1";
    return `${l.pathname}${search}${l.hash}`;
};
